// Level is the closed set of bump levels: major, minor, or patch.
// ParseLevel accepts the raw strings at input boundaries (CLI flags, config)
// and rejects typos with an error naming the valid set.
type Level string

const (
	LevelMajor Level = "major"
	LevelMinor Level = "minor"
	LevelPatch Level = "patch"
)

func AllLevel() []Level {
	return []Level{LevelMajor, LevelMinor, LevelPatch}
}

func ParseLevel(s string) (Level, error) {
	switch s {
	case "major":
		return LevelMajor, nil
	case "minor":
		return LevelMinor, nil
	case "patch":
		return LevelPatch, nil
	}
	switch s {
	case "Major":
		return LevelMajor, nil
	case "Minor":
		return LevelMinor, nil
	case "Patch":
		return LevelPatch, nil
	}
	var zero Level
	return zero, fmt.Errorf("invalid Level %q (valid: \"major\", \"minor\", \"patch\")", s)
}

func (e Level) String() string {
	return string(e)
}

// Version represents a parsed semver tag. Fields are public value-type
// fields — read them directly (v.Major, v.Prefix); construct via Parse.
type Version struct {
	Major  int
	Minor  int
	Patch  int
	Prefix string
}

// Parse converts a semver string like "v1.2.3" or "1.2.3" into a Version
// Returns an error if the string is not valid semver
// Example: v := semver.Parse("v1.2.3") onerr return
// Semver implements a narrow three-integer version contract (major.minor.patch)
// with an optional "v" prefix. It is NOT full SemVer 2.0: prerelease
// (1.0.0-alpha) and build metadata (1.0.0+build) are rejected, and leading
// zeros (01.02.03) are rejected. See audit blocker resolution.
func Parse(tag string) (Version, error) {
	raw := tag
	prefix := ""
	if kukistring.HasPrefix(raw, "v") {
		prefix = "v"
		raw = kukistring.TrimPrefix(raw, "v")
	}
	parts := kukistring.Split(raw, ".")
	if len(parts) != 3 {
		return Version{}, fmt.Errorf("invalid semver: %v", tag)
	}
	for _, p := range parts {
		if len(p) > 1 && kukistring.HasPrefix(p, "0") {
			return Version{}, fmt.Errorf("invalid semver: leading zero not allowed: %v", tag)
		}
	}
	major, err := parse.Int(parts[0])
	if err != nil {
		return Version{}, fmt.Errorf("invalid semver: %v", tag)
	}
	minor, err_1 := parse.Int(parts[1])
	if err_1 != nil {
		return Version{}, fmt.Errorf("invalid semver: %v", tag)
	}
	patch, err_2 := parse.Int(parts[2])
	if err_2 != nil {
		return Version{}, fmt.Errorf("invalid semver: %v", tag)
	}
	if major < 0 || minor < 0 || patch < 0 {
		return Version{}, fmt.Errorf("invalid semver: %v", tag)
	}
	return Version{Major: major, Minor: minor, Patch: patch, Prefix: prefix}, nil
}

// Bump increments the version by the given level
// Higher components are incremented and lower ones are zeroed
// Example: v |> semver.Bump(semver.Level.Minor)
func Bump(v Version, level Level) Version {
	switch level {
	case LevelMajor:
		v.Major += 1
		v.Minor = 0
		v.Patch = 0
	case LevelMinor:
		v.Minor += 1
		v.Patch = 0
	case LevelPatch:
		v.Patch += 1
	}
	return v
}

// Format converts a Version back to its string form (e.g. "v1.2.3")
// Example: tag := v |> semver.Format()
func Format(v Version) string {
	return fmt.Sprintf("%v%v.%v.%v", v.Prefix, v.Major, v.Minor, v.Patch)
}

// Valid returns true if the tag string is valid semver
// Example: if semver.Valid("v1.0.0")
func Valid(tag string) bool {
	_, err := Parse(tag)
	if err != nil {
		return false
	}
	return true
}

// Compare returns -1, 0, or 1 comparing two versions
// Example: semver.Compare(a, b)
func Compare(a Version, b Version) int {
	if a.Major != b.Major {
		if a.Major > b.Major {
			return 1
		}
		return -1
	}
	if a.Minor != b.Minor {
		if a.Minor > b.Minor {
			return 1
		}
		return -1
	}
	if a.Patch != b.Patch {
		if a.Patch > b.Patch {
			return 1
		}
		return -1
	}
	return 0
}

// Greater returns true if a is greater than b
// Example: semver.Greater(a, b)
func Greater(a Version, b Version) bool {
	return Compare(a, b) > 0
}

// Highest returns the highest valid semver tag from a list of strings
// Non-semver strings are silently ignored
// Example: best := semver.Highest(tags) onerr return
func Highest(tags []string) (string, error) {
	valid := slice.Filter(tags, Valid)
	if len(valid) == 0 {
		return "", errors.New("no valid semver tags found")
	}
	parsed := make([]Version, 0, len(valid))
	for _, tag := range valid {
		v, err := Parse(tag)
		if err != nil {
			continue
		}
		parsed = append(parsed, v)
	}
	sorted := sort.By(parsed, func(a Version, b Version) bool { return Compare(a, b) < 0 })
	best := sorted[len(sorted)-1]
	return Format(best), nil
}
